using System.Reflection;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Threading;using System.Diagnostics;using SuperDock;
class Check{
[DllImport("user32.dll")]static extern bool SetCursorPos(int x,int y);[StructLayout(LayoutKind.Sequential)]struct Pt{public int X,Y;}[DllImport("user32.dll")]static extern bool GetCursorPos(out Pt p);
static void Wait(int ms){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(_,_)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
[STAThread]static void Main(){GetCursorPos(out var cursor);var app=new App();app.InitializeComponent();app.ShutdownMode=ShutdownMode.OnExplicitShutdown;var flags=BindingFlags.Instance|BindingFlags.NonPublic;var settings=new MainWindow.Settings{Entries=[],Groups=[new("悬停测试甲",[]),new("悬停测试乙",[])],ClockWidget=false,PerformanceWidget=false,WeatherWidget=false,ShowFileSearch=false,ShowExitButton=false,ShowDirectionArrows=false,AutoHide=false,SmartLayering=false,HoverScale=1};var window=(MainWindow)Activator.CreateInstance(typeof(MainWindow),flags,null,new object[]{settings,false},null)!;try{window.Show();window.UpdateLayout();Wait(200);var panel=(StackPanel)typeof(MainWindow).GetField("panel",flags)!.GetValue(window)!;var anchors=panel.Children.OfType<FrameworkElement>().Where(x=>x.Tag is string s&&s.StartsWith("group:")).ToArray();Popup? Popup()=> (Popup?)typeof(MainWindow).GetField("groupFlyout",flags)!.GetValue(window);void Move(FrameworkElement anchor){var point=anchor.PointToScreen(new Point(anchor.ActualWidth/2,anchor.ActualHeight/2));SetCursorPos((int)point.X,(int)point.Y);}
void Hover(FrameworkElement anchor,int ms){for(int elapsed=0;elapsed<ms;elapsed+=50){Move(anchor);Wait(50);}}
Hover(anchors[0],120);if(Popup()?.IsOpen==true)throw new Exception("Opened too early");Hover(anchors[0],600);if(Popup()?.IsOpen!=true)throw new Exception("Hover failed");Console.WriteLine("PASS delayed hover opens");Hover(anchors[0],1600);if(Popup()?.IsOpen!=true)throw new Exception("Anchor keep-open failed");Console.WriteLine("PASS stays open on anchor");Hover(anchors[1],900);if(!ReferenceEquals(typeof(MainWindow).GetField("expandedGroup",flags)!.GetValue(window),settings.Groups[1])||Popup()?.IsOpen!=true)throw new Exception("Switch failed expanded="+((MainWindow.AppGroup)typeof(MainWindow).GetField("expandedGroup",flags)!.GetValue(window))?.Name+" candidate="+((MainWindow.AppGroup)typeof(MainWindow).GetField("groupHoverCandidate",flags)!.GetValue(window))?.Name+" open="+Popup()?.IsOpen+" menus="+typeof(MainWindow).GetField("openMenus",flags)!.GetValue(window));Console.WriteLine("PASS switches groups");var child=(FrameworkElement)Popup()!.Child;Hover(child,600);if(Popup()?.IsOpen!=true)throw new Exception("Popup keep-open failed");Console.WriteLine("PASS stays open on popup");SetCursorPos(500,100);Wait(850);if(Popup()?.IsOpen==true)throw new Exception("Dismiss failed");Console.WriteLine("PASS dismisses after leaving");}finally{window.Close();SetCursorPos(cursor.X,cursor.Y);app.Shutdown();}}
}
